void pao(int x, int y, int &rez) {
    long long inv = 0, dir = 0, p = 1;
    while (x > 0) {
        int c = x % 10;
        if (c != 0 && c % 2 == 0) inv = inv * 10 + c;
        x = x / 10;
    }
    while (y > 0) {
        int c = y % 10;
        if (c != 0 && c % 2 == 0) {
            dir = dir + c * p;
            p = p * 10;
        }
        y = y / 10;
    }
    rez = (inv == dir && inv > 0);
}
