        long long p = 1;
        for (int d = 1; d <= x && p <= x; d = d + 2)
            if (x % d == 0) p = p * d;
        if (p > x) return x;
    }
    return 0;
}
int main() {
    int a, b;
    cin >> a >> b;
    cout << MaxImp(a, b);
    return 0;
}

