}

#include <iostream>
using namespace std;
// total[e] = punctajul echipei e, maxim[e] = câte probleme are cu 99 de puncte
int total[100], maxim[100];
bool inscrisa[100];
int main() {
    int x;
    while (cin >> x) {
        int echipa = x % 100, punctaj;
        if (x >= 10000) punctaj = x / 100 % 100;   // punctaj din două cifre
        else punctaj = x / 100 % 10;               // punctaj dintr-o cifră
        total[echipa] += punctaj;
        if (punctaj == 99) maxim[echipa]++;
        inscrisa[echipa] = true;
    }
    int prima = 0;
    for (int e = 10; e <= 99; e++)   // în ordinea înscrierii
        if (inscrisa[e] && (prima == 0 || total[e] > total[prima] ||
            (total[e] == total[prima] && maxim[e] > maxim[prima])))
            prima = e;
    cout << prima;
    return 0;
}
